import * as mongoose from 'mongoose';
import {
  IInventory
} from '../../interfaces/inventory.interface';

const invetoryCommentCars = new mongoose.Schema({
  user: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User'
  },
  comment: {
    type: String
  },
  createdAt: {
    type: Date,
    default: new Date()
  }
});

export enum ChoicesStatusCarInventory {
  pending = 'pending',
  found = 'found',
  missing = 'missing',
  leftover = 'leftover',
  reported = 'reported'
}
export const choicesStatusCarInventory = [
  ChoicesStatusCarInventory.pending,
  ChoicesStatusCarInventory.found,
  ChoicesStatusCarInventory.leftover,
  ChoicesStatusCarInventory.missing,
  ChoicesStatusCarInventory.reported
];

const inventoryCarSchema = new mongoose.Schema({
  inventory: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Inventory'
  },
  car: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Car'
  },
  venue: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Venue'
  },
  venueFound: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Venue'
  },
  inventoriedBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User'
  },
  images: [{
    type: mongoose.Schema.Types.ObjectId,
    ref: 'InventoryFile'
  }],
  comments: [invetoryCommentCars],
  label: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'InventoryLabel'
  },
  labelText: {
    type: String,
    default: ''
  },
  labelBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User'
  },
  customizedStatusText: {
    type: String,
    default: ''
  },
  status: {
    type: String,
    enum: choicesStatusCarInventory,
    default: ChoicesStatusCarInventory.pending
  }
}, {
  timestamps: true
});
console.log(inventoryCarSchema);

export interface IInventoryModel extends IInventory, mongoose.Document {}
export enum ChoicesStatusInventory {
  pending = 'pending',
  inProcess = 'inProcess',
  finalized = 'finalized'
}
export const choicesStatusInventory = [
  ChoicesStatusInventory.pending,
  ChoicesStatusInventory.inProcess,
  ChoicesStatusInventory.finalized
];
const inventorySchema = new mongoose.Schema({
  name: {
    type: String
  },
  team: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Team',
    required: true
  },
  company: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Company',
    required: true
  },
  venues: [{
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Venue'
  }],
  createdBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User'
  },
  finalizedBy: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User'
  },
  finalizedAt: {
    type: Date
  },
  status: {
    type: String,
    enum: choicesStatusInventory,
    default: ChoicesStatusInventory.pending
  }
}, {
  timestamps: true
});

inventorySchema.virtual('cars', {
  ref: 'InventoryCar', // The model to use
  localField: '_id', // Find field in this model
  foreignField: 'inventory', // is equal to field in another model
  justOne: false
});

inventorySchema.index({team: 1});
inventorySchema.index({team: 1, status: 1, venues: 1});
const Inventory = mongoose.model<IInventoryModel>('Inventory', inventorySchema);

export default Inventory;
